// use_figma script (READ-ONLY). Generated by `python3 scripts/figma-script.py check …` — do not edit by hand.
// For each component: props vs the Magma code API, matrix completeness, description,
// values not bound to tokens (the "linter"), content overflowing the component.
// Figma-only properties and code props left out are read from the component description:
//   "Figma-only: a (why), b (why)."   and   "Not in Figma: x (why)."
/*__CONFIG__*/
const CONVENTION = { state: 'visual state', focus: 'focus ring' }; // conventions.md#props

// names listed after a label in the description, e.g. "Figma-only: slot (swap it), content and size (why)."
const listed = (desc, labels) => {
  const out = new Set();
  for (const label of labels) {
    const re = new RegExp(label + '\\s*:([^\\n]*)', 'gi');
    let m;
    while ((m = re.exec(desc))) {
      let s = m[1],
        depth = 0,
        flat = '';
      for (const ch of s) {
        if (ch === '(') depth++;
        else if (ch === ')') depth--;
        else if (!depth) flat += ch;
      }
      flat = flat.split(/\.(\s|$)/)[0];
      for (const part of flat.split(/,|\band\b|;/)) {
        const n = part.replace(/[`"']/g, '').trim();
        if (n) out.add(n);
      }
    }
  }
  return out;
};

const results = [];
for (const R of RUNS) {
  const ko = [],
    warn = [],
    info = [];
  const comp = await figma.getNodeByIdAsync(R.id);
  if (!comp) {
    results.push({ id: R.id, ko: ['node not found'] });
    continue;
  }
  const isSet = comp.type === 'COMPONENT_SET';
  if (comp.type === 'COMPONENT' && comp.parent && comp.parent.type === 'COMPONENT_SET') {
    results.push({
      id: R.id,
      ko: ['this is a variant: pass the component set id ' + comp.parent.id],
    });
    continue;
  }
  const variants = isSet ? comp.children.filter((c) => c.type === 'COMPONENT') : [comp];
  const defs = comp.componentPropertyDefinitions;
  const desc = comp.description || '';
  const plain = desc
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&');
  const FIGMA_ONLY = listed(plain, ['Figma-only', 'Figma only']);
  const OMITTED = listed(plain, ['Not in Figma']);
  const API = R.api;
  const lc = (s) => s.toLowerCase().replace(/[^a-z0-9]/g, '');

  // 0. the description names the right tag
  const tagInDesc = (plain.match(/^Magma <(mds-[\w-]+)>/) || [])[1];
  if (!tagInDesc)
    warn.push('description does not start with "Magma <mds-…>." (conventions.md#description)');
  else if (tagInDesc !== API.tag)
    ko.push(
      `description says <${tagInDesc}> but the check was run for <${API.tag}>: wrong id or wrong tag`,
    );

  // 1. props vs code
  const figmaProps = {};
  for (const [k, d] of Object.entries(defs)) figmaProps[k.split('#')[0]] = d;
  const codeProps = API.props;
  if (!Object.keys(codeProps).length) info.push(`<${API.tag}> has no props in the code`);
  for (const [name, d] of Object.entries(figmaProps)) {
    const code = codeProps[name];
    if (!code) {
      if (FIGMA_ONLY.has(name) || CONVENTION[name]) {
        info.push(`${name}: Figma-only${CONVENTION[name] ? ' (' + CONVENTION[name] + ')' : ''}`);
        continue;
      }
      const near = Object.keys(codeProps).find(
        (p) => lc(p) === lc(name) || lc(name).includes(lc(p)) || lc(p).includes(lc(name)),
      );
      ko.push(
        near
          ? `prop "${name}" is written differently in the code: "${near}"`
          : `prop "${name}" is not a code prop: rename it, or list it in the description after "Figma-only:" with the reason`,
      );
      continue;
    }
    if (d.type === 'VARIANT') {
      const fv = d.variantOptions;
      if (code.kind === 'enum' || code.kind === 'boolean') {
        const extra = fv.filter((v) => !code.values.includes(v));
        const missing = code.values.filter(
          (v) => !fv.includes(v) && !OMITTED.has(name + '=' + v) && !OMITTED.has(name),
        );
        if (extra.length)
          ko.push(
            `${name}: values not in the code ${JSON.stringify(extra)} (code: ${code.values.join('|')})`,
          );
        if (missing.length)
          warn.push(
            `${name}: code values missing in Figma ${JSON.stringify(missing)} — add them, or list them after "Not in Figma:" with the reason`,
          );
      } else if (code.kind === 'number') {
        const bad = fv.filter((v) => isNaN(Number(v)));
        if (bad.length)
          ko.push(`${name}: code is a number, Figma values ${JSON.stringify(bad)} are not`);
      } else warn.push(`${name}: VARIANT in Figma but "${code.kind}" in the code`);
      const def = isSet ? comp.defaultVariant.variantProperties[name] : null;
      if (code.default != null && def != null && def !== String(code.default))
        warn.push(`${name}: default variant is "${def}", code default is "${code.default}"`);
    }
    if (d.type === 'BOOLEAN' && code.kind !== 'boolean')
      warn.push(`${name}: BOOLEAN in Figma but "${code.kind}" in the code`);
    if (
      d.type === 'BOOLEAN' &&
      code.kind === 'boolean' &&
      code.default != null &&
      String(d.defaultValue) !== String(code.default)
    )
      warn.push(`${name}: default ${d.defaultValue}, code default ${code.default}`);
  }
  for (const [name, c] of Object.entries(codeProps)) {
    if (figmaProps[name] || OMITTED.has(name)) continue;
    if (c.kind === 'enum' || c.kind === 'boolean')
      warn.push(
        `code prop "${name}" (${c.kind}${c.values ? ': ' + c.values.join('|') : ''}) has no Figma property — add it, or list it after "Not in Figma:" with the reason`,
      );
  }

  // 2. matrix completeness
  if (isSet) {
    const full = Object.values(defs)
      .filter((d) => d.type === 'VARIANT')
      .reduce((a, d) => a * d.variantOptions.length, 1);
    if (variants.length < full && !/Combinations/i.test(plain))
      warn.push(
        `${variants.length} of ${full} combinations exist: write "Combinations: … only with …" in the description`,
      );
  }

  // 3. description
  if (!plain.trim()) ko.push('empty description');
  if (/&amp;(amp|quot|lt|gt|#39|apos|nbsp);/.test(desc))
    ko.push('description stores HTML entities: write it as plain text');

  // 4. linter: every visual value bound to a token (own layers; nested instances are checked on their own component)
  const issues = {};
  const add = (what, node, v) => {
    const key = what + ' · ' + node.name;
    (issues[key] = issues[key] || new Set()).add(v.name);
  };
  const rawSolid = (ps) =>
    Array.isArray(ps) &&
    ps.some(
      (p) =>
        p.visible !== false && p.type === 'SOLID' && !(p.boundVariables && p.boundVariables.color),
    );
  const walk = (n, v) => {
    if (n.visible === false) return;
    if ('fills' in n && n.fillStyleId === '' && rawSolid(n.fills))
      add('fill not bound to a variable', n, v);
    if ('strokes' in n && n.strokeStyleId === '' && rawSolid(n.strokes))
      add('stroke not bound to a variable', n, v);
    const bv = n.boundVariables || {};
    if (
      'strokes' in n &&
      n.strokes.some((p) => p.visible !== false) &&
      typeof n.strokeWeight === 'number' &&
      n.strokeWeight > 0 &&
      !bv.strokeWeight &&
      !bv.strokeTopWeight
    )
      add('stroke weight not bound', n, v);
    if ('layoutMode' in n && n.layoutMode !== 'NONE') {
      if (n.itemSpacing > 0 && !bv.itemSpacing && n.primaryAxisAlignItems !== 'SPACE_BETWEEN')
        add('gap not bound', n, v);
      for (const p of ['paddingLeft', 'paddingRight', 'paddingTop', 'paddingBottom'])
        if (n[p] > 0 && !bv[p]) {
          add('padding not bound', n, v);
          break;
        }
    }
    if ('topLeftRadius' in n && n.type !== 'TEXT') {
      const r = [n.topLeftRadius, n.topRightRadius, n.bottomLeftRadius, n.bottomRightRadius];
      if (r.some((x) => x > 0) && !bv.topLeftRadius && !bv.cornerRadius)
        add('radius not bound', n, v);
    }
    // mixed styles are fine when every segment has one (e.g. a bold label + regular value)
    if (
      n.type === 'TEXT' &&
      (n.textStyleId === '' ||
        (n.textStyleId === figma.mixed &&
          !n.getStyledTextSegments(['textStyleId']).every((s) => s.textStyleId)))
    )
      add('text without a text style', n, v);
    if (
      'effects' in n &&
      n.effects.some((e) => e.visible) &&
      n.effectStyleId === '' &&
      !n.effects.every((e) => e.boundVariables && Object.keys(e.boundVariables).length)
    )
      add('effect without an effect style', n, v);
    if (n.type === 'INSTANCE') return;
    if ('children' in n) for (const c of n.children) walk(c, v);
  };
  for (const v of variants) walk(v, v);
  for (const [k, set] of Object.entries(issues))
    ko.push(`${k} — in ${set.size} of ${variants.length} variants (e.g. "${[...set][0]}")`);

  // 5. content outside the component; focus rings may go out
  const overflow = {};
  for (const v of variants) {
    const vb = v.absoluteBoundingBox;
    for (const n of v.findAll(
      (x) =>
        x.visible !== false && (x.type === 'TEXT' || x.type === 'INSTANCE' || x.type === 'FRAME'),
    )) {
      let a = n,
        skip = false;
      while (a && a !== v) {
        if (/focus/i.test(a.name)) {
          skip = true;
          break;
        }
        a = a.parent;
      }
      if (skip) continue;
      const rb = n.absoluteRenderBounds;
      if (!rb) continue;
      const out = Math.max(
        vb.x - rb.x,
        rb.x + rb.width - (vb.x + vb.width),
        vb.y - rb.y,
        rb.y + rb.height - (vb.y + vb.height),
      );
      if (out > 2)
        (overflow[n.name] = overflow[n.name] || []).push(v.name + ' (+' + Math.round(out) + 'px)');
    }
  }
  for (const [k, list] of Object.entries(overflow))
    ko.push(
      `"${k}" goes outside the component in ${list.length} variants, e.g. ${list.slice(0, 3).join('; ')}`,
    );

  // 6. hygiene
  if (variants.some((v) => v.clipsContent) && comp.findOne((n) => /focus/i.test(n.name)))
    warn.push('some variants clip content: the focus ring may be cut (clipsContent = false)');

  results.push({
    component: comp.name,
    id: R.id,
    tag: API.tag,
    variants: variants.length,
    ko,
    warn,
    info,
  });
}
const totalKo = results.reduce((a, r) => a + r.ko.length, 0);
return { verdict: totalKo ? `${totalKo} KO — fix and re-run` : 'OK — 0 KO', results };
